// Selected official TopRankTeamItem; generated by prepare_activity_battle_rank_ui.py.
using Zjcs.Official.WorldUI;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.TeamUI;
namespace Zjcs.Official.ActivityRankUI
{
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class TopRankTeamItem : UIBase
{
	[SerializeField]
	protected WorldMultiLanguageText mRankText;

	[SerializeField]
	protected List<WorldMultiLanguageText> mScoreTexts;

	[SerializeField]
	protected TeamMemberIcon[] mTeamMemberIcons;

	[SerializeField]
	protected WorldStateSwitcher<bool> mMeStateSwitcher;

	[SerializeField]
	protected WorldStateSwitcher<int> mTopStateSwticher;

	protected TeamTopContentData mData;
	private ActivityRankBindings bindings;
	public void Configure(ActivityRankBindings value)
	{ bindings = value; foreach (var icon in mTeamMemberIcons) icon.Configure(value.Icons); }

	protected override void OnEnableAndInited()
	{
		base.OnEnableAndInited();
		Refresh();
	}

	public void Init(TeamTopContentData data)
	{
		InitWrapper(() =>
		{
			mData = data;
			mMeStateSwitcher.SetState(data.IsMySelf);
		});
	}

	protected virtual void Refresh()
	{
		if (mData.Rank < bindings.ShowPlayerCountLimit)
		{
			mRankText.SetKey("{0}", mData.Rank + 1);
		}
		else
		{
			mRankText.SetKey("-");
		}
		mTopStateSwticher.SetState(mData.Rank + 1);
		IEnumerator<WorldMultiLanguageText> enumerator = mScoreTexts.GetEnumerator();
		foreach (object score in GetScores(mData.Score))
		{
			if (!enumerator.MoveNext())
			{
				break;
			}
			enumerator.Current.Format(score);
		}
		int i = 0;
		foreach (long playerId in mData.PlayerIds)
		{
			mTeamMemberIcons[i].Init(bindings.PlayerTarget(playerId), i == 0);
			i++;
		}
		foreach (ActivityRankNpcTarget npcTargetData in mData.NpcTargetDatas)
		{
			mTeamMemberIcons[i].InitNpcIcon(npcTargetData.NpcClassId, mData.LevelSubRankData.Level, mData.LevelSubRankData.SubRank);
			i++;
		}
		for (; i < mTeamMemberIcons.Length; i++)
		{
			mTeamMemberIcons[i].Init(null, isLeader: false);
		}
	}

	public static IEnumerable GetScores(object scores)
	{
		if (scores is string text)
		{
			yield return text;
		}
		else if (scores is IEnumerable enumerable)
		{
			foreach (object item in enumerable)
			{
				yield return item;
			}
		}
		else
		{
			yield return scores;
		}
	}
}
}
